package dev.myjarvis.core;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class StudyFeedbackServiceTest extends StudyFeedbackFixtures {
    @Test void genuineSavedAnswerUsesExactFourFiveFourPhasesWithoutStudyOrTranscriptWrites(){
        saveTwo();long before=conversationVersion(targetConversation),messages=count("messages"),mutations=count("study_mutations"),jobs=count("jobs");
        UUID id=requestFeedback(0);assertEquals(before+4,conversationVersion(targetConversation));
        assertEquals(feedbackRow(id).get("updated_at"),db.queryForObject("SELECT committed_at FROM study_feedback_events WHERE feedback_id=? AND version=1",Object.class,id));
        assertFalse(AuthService.instant(feedbackRow(id).get("updated_at")).isBefore(AuthService.instant(feedbackRow(id).get("created_at"))));
        var dispatch=dispatch(id);assertEquals(before+9,conversationVersion(targetConversation));
        var response=StudyFeedbackResultTest.response(dispatch.body());context.getBean(UsageService.class).record(dispatch,response);feedback.settle(dispatch,response);
        assertEquals(before+13,conversationVersion(targetConversation));assertEquals("ACCEPTED",feedbackRow(id).get("state"));
        assertEquals(3L,((Number)view(studyId).get("version")).longValue());assertEquals(mutations,count("study_mutations"));assertEquals(messages,count("messages"));assertEquals(jobs,count("jobs"));
        var run=db.queryForMap("SELECT result_ref,context_history_eligible FROM runs WHERE id=?",dispatch.run());assertNull(run.get("result_ref"));assertEquals(false,run.get("context_history_eligible"));
        assertEquals(3L,db.queryForObject("SELECT count(*) FROM study_feedback_events WHERE feedback_id=?",Long.class,id));
        assertEquals(1L,db.queryForObject("SELECT count(*) FROM inference_usage_receipts WHERE reservation_id=? AND response_kind='FEEDBACK'",Long.class,dispatch.reservation()));
    }
    @Test void exactReceiptReplaySurvivesUnavailableRuntimeWithoutAnyNewWork(){saveTwo();UUID key=UUID.randomUUID();var body=requestBody(0);var first=feedback.request(session,key,studyId,body);long version=conversationVersion(targetConversation),runs=count("runs");feedbackClient.available=false;assertEquals(receipt(first),receipt(feedback.request(session,key,studyId,body)));assertEquals(version,conversationVersion(targetConversation));assertEquals(runs,count("runs"));assertEquals(0,feedbackClient.calls);assertEquals(receipt(first),receipt(feedback.mutation(session,key)));}
    @Test void explicitSharedSchedulerRunsExactlyOneDedicatedGeneration(){saveTwo();UUID id=requestFeedback(0);assertTrue(feedbackLocal.runOne());assertFalse(feedbackLocal.runOne());assertEquals(1,feedbackClient.calls);assertEquals("ACCEPTED",feedbackRow(id).get("state"));assertFalse(feedbackClient.lastBody.has("user_input"));assertTrue(feedbackClient.lastBody.get("history").isEmpty());assertTrue(feedbackClient.lastBody.get("memories").isEmpty());assertEquals("UTC",feedbackClient.lastBody.get("timezone").asText());}
    @Test void failedOrRevokedInputIsConsumedForLife(){saveTwo();UUID id=requestFeedback(0);feedback.revoke(session,UUID.randomUUID(),id,revokeBody(id));assertThrows(ApiException.class,()->requestFeedback(0));assertEquals(1L,count("study_feedback_requests"));assertEquals(0,feedbackClient.calls);}
    @Test void queuedOwnerRevokeClosesOutputWithFourWritesAndNoClaimedStop()throws Exception {saveTwo();UUID id=requestFeedback(0);long before=conversationVersion(targetConversation);var result=feedback.revoke(session,UUID.randomUUID(),id,revokeBody(id));assertEquals(before+4,conversationVersion(targetConversation));assertEquals("REVOKE_FEEDBACK",receipt(result).get("operation"));assertEquals("REVOKED",feedbackRow(id).get("state"));assertFalse(quiescent(id));proof(id,"UNSTARTED_CORE");assertTrue(quiescent(id));assertEquals(0,feedbackClient.calls);}
    @Test void timeoutRevokesDispatchedAuthorityAndPreservesUnknownExpense(){saveTwo();long before=conversationVersion(targetConversation);UUID id=requestFeedback(0);feedbackClient.failInfer=true;assertTrue(feedbackLocal.runOne());assertEquals(before+13,conversationVersion(targetConversation));var row=feedbackRow(id);assertEquals("REVOKED",row.get("state"));assertEquals("UNKNOWN",db.queryForObject("SELECT status FROM inference_reservations WHERE id=?",String.class,row.get("reservation_id")));assertNull(row.get("result_ref"));assertFalse(quiescent(id));assertEquals(1,feedbackClient.calls);assertFalse(feedbackLocal.runOne());}
    @Test void completeErrorIsFailedUncertainAndFencesOnlyThroughClosedOutputDecision()throws Exception {saveTwo();long before=conversationVersion(targetConversation);UUID id=requestFeedback(0);feedbackClient.kind="ERROR";assertTrue(feedbackLocal.runOne());assertEquals(before+13,conversationVersion(targetConversation));assertEquals("FAILED",feedbackRow(id).get("state"));assertFalse(quiescent(id));feedbackClient.proofKind="UNSTARTED_FENCED";feedbackLocal.controls.reconcileOne(owner,(UUID)feedbackRow(id).get("reservation_id"));assertEquals("FEEDBACK_OUTPUT_CLOSED",db.queryForObject("SELECT decision FROM inference_control_slots WHERE reservation_id=?",String.class,feedbackRow(id).get("reservation_id")));assertTrue(quiescent(id));assertEquals("FAILED",feedbackRow(id).get("state"));assertEquals("ERROR",db.queryForObject("SELECT receipt_kind FROM inference_usage_receipts WHERE reservation_id=?",String.class,feedbackRow(id).get("reservation_id")));}
    @Test void lateMeasuredReceiptCommitsWithoutRestoringRevokedOutput(){saveTwo();UUID id=requestFeedback(0);var dispatch=dispatch(id);feedback.revoke(session,UUID.randomUUID(),id,revokeBody(id));long version=conversationVersion(targetConversation);var response=StudyFeedbackResultTest.response(dispatch.body());context.getBean(UsageService.class).record(dispatch,response);feedback.settle(dispatch,response);assertEquals(version,conversationVersion(targetConversation));assertEquals("REVOKED",feedbackRow(id).get("state"));assertNull(feedbackRow(id).get("result_ref"));assertEquals(1L,db.queryForObject("SELECT count(*) FROM inference_usage_receipts WHERE reservation_id=? AND receipt_kind='MEASURED'",Long.class,dispatch.reservation()));}
    @Test void sourceDeletionPrecedesUnavailableReadinessAndReceiptLookupIsMetadataOnly(){saveTwo();commit(prepare(targetConversation),UUID.randomUUID());feedbackClient.available=false;var body=json(Map.of("expected_study_version",3,"expected_conversation_version",1,"question_id",UUID.randomUUID(),"input_id",UUID.randomUUID(),"attempt_id",UUID.randomUUID()));error(()->feedback.request(session,UUID.randomUUID(),studyId,body),410,"CONVERSATION_DELETED");assertEquals("NOT_OBSERVED",feedback.mutation(session,UUID.randomUUID()).get("status"));assertEquals(0L,count("study_feedback_requests"));}
    @Test void existingOperationKeyUsesOriginalTargetBeforeSuppliedMissingTarget(){saveTwo();UUID key=UUID.randomUUID();var body=requestBody(0);feedback.request(session,key,studyId,body);error(()->feedback.request(session,key,UUID.randomUUID(),body),409,"IDEMPOTENCY_CONFLICT");UUID id=(UUID)receipt(feedback.mutation(session,key)).get("feedback_request_id");UUID revokeKey=UUID.randomUUID();var revoke=revokeBody(id);feedback.revoke(session,revokeKey,id,revoke);error(()->feedback.revoke(session,revokeKey,UUID.randomUUID(),revoke),409,"IDEMPOTENCY_CONFLICT");}
    @Test void closedUnprovenFeedbackKeepsSecondTargetUnavailable()throws Exception {saveTwo();UUID id=requestFeedback(0);complete(id);var view=Json.MAPPER.valueToTree(feedback.read(session,studyId));assertEquals("CONVERSATION_BUSY",view.path("targets").get(1).path("availability").asText());proof(id,"COMPLETED");assertEquals("AVAILABLE",Json.MAPPER.valueToTree(feedback.read(session,studyId)).path("targets").get(1).path("availability").asText());}
    @Test void oneActiveAcrossInputsAndTwoLifetimeTargetsRemainConjunctive()throws Exception {
        saveTwo();UUID first=requestFeedback(0);long version=conversationVersion(targetConversation);assertThrows(ApiException.class,()->requestFeedback(1));assertEquals(version,conversationVersion(targetConversation));assertEquals(1L,count("study_feedback_requests"));
        feedback.revoke(session,UUID.randomUUID(),first,revokeBody(first));proof(first,"UNSTARTED_CORE");UUID second=requestFeedback(1);feedback.revoke(session,UUID.randomUUID(),second,revokeBody(second));proof(second,"UNSTARTED_CORE");
        for(int target:List.of(0,1))assertThrows(ApiException.class,()->requestFeedback(target));assertEquals(2L,count("study_feedback_requests"));assertEquals(0,feedbackClient.calls);
    }
    @Test void exactMeasuredReplayIsReadOnlyAndConflictingFeedbackUsageCannotReplaceIt(){
        saveTwo();UUID id=requestFeedback(0);var dispatch=dispatch(id);var response=StudyFeedbackResultTest.response(dispatch.body());var usage=context.getBean(UsageService.class);usage.record(dispatch,response);var rows=db.queryForList("SELECT * FROM inference_usage_receipts WHERE reservation_id=?",dispatch.reservation());long version=conversationVersion(targetConversation);usage.record(dispatch,response);assertEquals(rows,db.queryForList("SELECT * FROM inference_usage_receipts WHERE reservation_id=?",dispatch.reservation()));
        var changed=response.deepCopy();((tools.jackson.databind.node.ObjectNode)changed.get("usage")).put("input_tokens",response.path("usage").path("input_tokens").asLong()+1);error(()->usage.record(dispatch,changed),409,"USAGE_MEASUREMENT_CONFLICT");assertEquals(rows,db.queryForList("SELECT * FROM inference_usage_receipts WHERE reservation_id=?",dispatch.reservation()));assertEquals(version,conversationVersion(targetConversation));assertEquals("RUNNING",feedbackRow(id).get("state"));
    }
    @Test void lateMeasuredFeedbackAfterActualDeletionCannotRestoreAnySource()throws Exception {
        saveTwo();UUID id=requestFeedback(0);var dispatch=dispatch(id);feedback.revoke(session,UUID.randomUUID(),id,revokeBody(id));proof(id,"WORKER_STOPPED");commit(prepare(targetConversation),UUID.randomUUID());
        var row=feedbackRow(id);long version=conversationVersion(targetConversation);var inventory=db.queryForMap("SELECT * FROM conversation_source_inventory_v18(?,?)",owner,targetConversation);var response=StudyFeedbackResultTest.response(dispatch.body());var usage=context.getBean(UsageService.class);var diagnostic=json(Map.of("kind","ERROR","error_code","MODEL_UNAVAILABLE","retryable",false,"usage",response.get("usage")));usage.record(dispatch,diagnostic);usage.record(dispatch,diagnostic);usage.record(dispatch,response);usage.record(dispatch,response);var conflict=json(Map.of("kind","ERROR","error_code","MODEL_OUTPUT_INVALID","retryable",false,"usage",response.get("usage")));error(()->usage.record(dispatch,conflict),409,"USAGE_MEASUREMENT_CONFLICT");feedback.settle(dispatch,response);
        assertEquals(row,feedbackRow(id));assertEquals(version,conversationVersion(targetConversation));assertEquals(inventory,db.queryForMap("SELECT * FROM conversation_source_inventory_v18(?,?)",owner,targetConversation));assertEquals(2L,db.queryForObject("SELECT count(*) FROM inference_usage_receipts WHERE reservation_id=?",Long.class,dispatch.reservation()));assertEquals(List.of("ERROR","MEASURED"),db.queryForList("SELECT receipt_kind FROM inference_usage_receipts WHERE reservation_id=? ORDER BY receipt_kind",String.class,dispatch.reservation()));assertNull(feedbackRow(id).get("source_binding_ref"));assertNull(feedbackRow(id).get("result_ref"));error(()->feedback.read(session,studyId),410,"CONVERSATION_DELETED");
    }
    @Test void ordinaryActiveUnknownAndPendingApprovalGraphsBlockFeedbackAdmission(){
        for(String kind:List.of("ACTIVE","UNKNOWN","APPROVAL")){
            saveTwo();var body=(tools.jackson.databind.node.ObjectNode)requestBody(0);UUID run=(UUID)flow.accept(session,targetConversation,json(Map.of("client_message_id",UUID.randomUUID(),"text",kind.equals("APPROVAL")?"/calendar":"Synthetic ordinary work","attachment_ids",List.of()))).get("run_id");
            if(kind.equals("UNKNOWN"))flow.tx.executeWithoutResult(t->{db.update("UPDATE jobs SET status='UNKNOWN' WHERE run_id=?",run);flow.setRun(owner,run,"UNKNOWN",null);});
            if(kind.equals("APPROVAL")){assertTrue(context.getBean(MockWorker.class).runOne());assertEquals("WAITING_APPROVAL",db.queryForObject("SELECT status FROM runs WHERE id=?",String.class,run));}
            body.put("expected_conversation_version",conversationVersion(targetConversation));long version=conversationVersion(targetConversation);assertThrows(ApiException.class,()->feedback.request(session,UUID.randomUUID(),studyId,body));assertEquals(version,conversationVersion(targetConversation));assertEquals(0L,count("study_feedback_requests"));
            if(kind.equals("ACTIVE"))flow.cancel(session,run,db.queryForObject("SELECT version FROM runs WHERE id=?",Long.class,run));
        }assertEquals(0,feedbackClient.calls);
    }
}
